Array.prototype.indexOf = function (a) {
    for (var b = 0; b < this.length; b++)
        if (this[b] == a)
            return b;
    return -1
};
Array.prototype.remove = function (a) {
    a = this.indexOf(a); -
        1 < a && this.splice(a, 1)
};
var writeUTF = function (a, b) {
    for (var c = [], d = 0, e = 0; e < a.length; e++) {
        var f = a.charCodeAt(e);
        if (0 <= f && 127 >= f)
            d += 1,
                c.push(f);
        else if (128 <= f && 2047 >= f)
            d += 2,
                c.push(192 | 31 & f >> 6),
                c.push(128 | 63 & f);
        else if (2048 <= f && 55295 >= f || 57344 <= f && 65535 >= f)
            d += 3,
                c.push(224 | 15 & f >> 12),
                c.push(128 | 63 & f >> 6),
                c.push(128 | 63 & f)
    }
    for (e = 0; e < c.length; e++)
        c[e] &= 255;
    return b ? c : 255 >= d ? [0, d].concat(c) : [d >> 8, d & 255].concat(c)
},
    toUTF8Hex = function (a) {
        a = writeUTF(a, !0);
        for (var b = "", c = 0; c < a.length; c++) {
            var d = (a[c] & 255).toString(16);
            1 === d.length && (d = "0" + d);
            b += d
        }
        return b
    };
