Blockly.Python.CocoRobo_init_assistant_wifi = function (a) {
    //Blockly.Python.definitions_.import_CocoRobo = "from CocoRobo import *";
    Blockly.Python.definitions_.import_bluebit = "from bluebit import *";
    Blockly.Python.definitions_.CocoRobo_bluebit_assistant_wifi = "def wifi_config(ssid, password):\n    data_len_L \x3d 96 \x26 0xff\n    data_len_H \x3d 96 \x3e\x3e 8\n    checkSum \x3d data_len_L + data_len_H + 0x01 + 0x01\n    n1 \x3d [0xff, 0x55, data_len_L, data_len_H, 0x01, 0x01]\n    wifi_ssid \x3d bytes(ssid, 'utf-8')\n    list_wifi_ssid \x3d [0]*32\n    for i in range(0,  len(wifi_ssid)):\n        list_wifi_ssid[i] \x3d wifi_ssid[i]\n    for i in range(0, 32):\n        checkSum +\x3d list_wifi_ssid[i]\n    wifi_pwd \x3d bytes(password, 'utf-8')\n    list_wifi_pwd \x3d [0]*64\n    for i in range(0,  len(wifi_pwd)):\n        list_wifi_pwd[i] \x3d wifi_pwd[i]\n    for i in range(0, 64):\n        checkSum +\x3d list_wifi_pwd[i]\n    n \x3d n1 + list_wifi_ssid + list_wifi_pwd\n    n.append(checkSum \x26 0xff)\n    return bytes(n)\n";
    var b = Blockly.Python.valueToCode(a, "ssid", Blockly.Python.ORDER_ATOMIC);
    a = Blockly.Python.valueToCode(a, "password", Blockly.Python.ORDER_ATOMIC);
    return ["wifi_config(" + b + ", " + a + ")", Blockly.Python.ORDER_ATOMIC]
};
Blockly.Python.CocoRobo_init_assistant_profile = function (a) {
    Blockly.Python.definitions_.CocoRobo_bluebit_assistant_profile = "def dueros_profile_config(duer_profile):\n    data_len_L \x3d len(duer_profile) \x26 0xff\n    data_len_H \x3d len(duer_profile) \x3e\x3e 8\n    checkSum \x3d data_len_L + data_len_H + 0x02 + 0x02\n    n1 \x3d [0xff, 0x55, data_len_L, data_len_H, 0x02, 0x02]\n    for i in range(0, len(duer_profile)):\n        checkSum +\x3d duer_profile[i]\n    n \x3d n1 + list(duer_profile)\n    n.append(checkSum \x26 0xff)\n    return bytes(n)\n";
    return "f \x3d open(" + Blockly.Python.valueToCode(a, "file_path", Blockly.Python.ORDER_ATOMIC) + ", 'rb')\nduer_profile \x3d f.read()\nprofile \x3d dueros_profile_config(duer_profile)\nf.close()\nuart1.write(profile)\n"
};
